/* GZCLP service worker (classic script). CONTRACTS §6 PWA.
 *
 * - precache.js (generated by tools/gen-precache.mjs) defines self.APP_VERSION and self.PRECACHE_URLS.
 * - All URLs are relative and resolved against the registration scope, so the app works
 *   from a subpath such as https://<user>.github.io/<repo>/.
 * - Cache-first for same-origin GETs; navigation falls back to the cached index.html offline.
 * - On activate after an update (an older gzclp-* cache existed) every window client gets
 *   { type: "sw-updated", version } so the UI can offer "Update available — reload".
 */
importScripts("./precache.js");

const VERSION = self.APP_VERSION;
const CACHE_PREFIX = "gzclp-";
const CACHE_NAME = CACHE_PREFIX + VERSION;
const scopeUrl = (path) => new URL(path, self.registration.scope).href;

self.addEventListener("install", (event) => {
  event.waitUntil(
    (async () => {
      const cache = await caches.open(CACHE_NAME);
      // cache: "reload" bypasses the HTTP cache so a new version never precaches stale files.
      await cache.addAll(self.PRECACHE_URLS.map((u) => new Request(scopeUrl(u), { cache: "reload" })));
      await self.skipWaiting();
    })()
  );
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    (async () => {
      const names = await caches.keys();
      const old = names.filter((n) => n.startsWith(CACHE_PREFIX) && n !== CACHE_NAME);
      await Promise.all(old.map((n) => caches.delete(n)));
      await self.clients.claim();
      if (old.length > 0) {
        const wins = await self.clients.matchAll({ type: "window", includeUncontrolled: true });
        for (const client of wins) client.postMessage({ type: "sw-updated", version: VERSION });
      }
    })()
  );
});

self.addEventListener("message", (event) => {
  if (event.data && event.data.type === "get-version" && event.source) {
    event.source.postMessage({ type: "sw-version", version: VERSION });
  }
});

self.addEventListener("fetch", (event) => {
  const req = event.request;
  if (req.method !== "GET") return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;

  const isNavigation = req.mode === "navigate";
  event.respondWith(
    (async () => {
      const cache = await caches.open(CACHE_NAME);
      const cached = await cache.match(req, { ignoreSearch: isNavigation });
      if (cached) return cached;
      try {
        return await fetch(req);
      } catch (err) {
        if (isNavigation) {
          const shell = await cache.match(scopeUrl("./index.html"));
          if (shell) return shell;
        }
        throw err;
      }
    })()
  );
});
